  static void Floral(Material material){string path="Assets/"+Folder+"/Materials/Original cobalt floral porcelain.asset";var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(texture==null){texture=new Texture2D(256,128,TextureFormat.RGBA32,false){name="Original cobalt blossom porcelain pattern",wrapMode=TextureWrapMode.Repeat};var pixels=new Color[256*128];for(int y=0;y<128;y++)for(int x=0;x<256;x++){float u=(x%64-32)/24f,v=(y%64-32)/24f,a=Mathf.Atan2(v,u),r=Mathf.Sqrt(u*u+v*v);bool petal=Mathf.Abs(r-(.45f+.14f*Mathf.Cos(a*5)))<.085f;bool leaf=Mathf.Abs(u+.7f*Mathf.Sin(v*3))<.045f&&Mathf.Abs(v)<1.2f;pixels[y*256+x]=petal||leaf?new Color(.04f,.18f,.48f):new Color(.95f,.97f,1);}texture.SetPixels(pixels);texture.Apply();AssetDatabase.CreateAsset(texture,path);}material.mainTexture=texture;EditorUtility.SetDirty(material);}
